"""Shared InnerAudio regression, old-denial control and handoff guard."""
import importlib.util,json,shutil,subprocess,tempfile,unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
JS='\'use strict\';\nconst fs=require(\'node:fs\'),vm=require(\'node:vm\'),assert=require(\'node:assert/strict\');\nconst path=require(\'node:path\'),root=process.argv[1];const oldSource="\\n  var audioLive = 0;\\n  function InnerAudio() {\\n    var a = new NAudio(), self = this, hs = {};\\n    audioLive++;\\n    [\'Canplay\', \'Play\', \'Pause\', \'Stop\', \'Ended\', \'Error\', \'TimeUpdate\', \'Waiting\', \'Seeking\', \'Seeked\'].forEach(function (n) {\\n      hs[n] = hub(); self[\'on\' + n] = hs[n].on; self[\'off\' + n] = hs[n].off;\\n    });\\n    a.addEventListener(\'canplay\', function () { hs.Canplay.emit(); });\\n    a.addEventListener(\'play\', function () { hs.Play.emit(); });\\n    a.addEventListener(\'pause\', function () { if (!self._stopping) hs.Pause.emit(); });\\n    a.addEventListener(\'ended\', function () { hs.Ended.emit(); });\\n    a.addEventListener(\'error\', function () { beacon(\'audio-error\', a.src); hs.Error.emit({ errMsg: \'audio error\', errCode: 10001 }); });\\n    a.addEventListener(\'timeupdate\', function () { hs.TimeUpdate.emit(); });\\n    a.addEventListener(\'waiting\', function () { hs.Waiting.emit(); });\\n    a.addEventListener(\'seeked\', function () { hs.Seeked.emit(); });\\n    Object.defineProperties(this, {\\n      src: { get: function () { return a.src; }, set: function (v) { a.src = v ? norm(v) : \'\'; } },\\n      loop: { get: function () { return a.loop; }, set: function (v) { a.loop = !!v; } },\\n      volume: { get: function () { return a.volume; }, set: function (v) { a.volume = Math.max(0, Math.min(1, +v || 0)); } },\\n      autoplay: { get: function () { return a.autoplay; }, set: function (v) { a.autoplay = !!v; } },\\n      startTime: { get: function () { return self._st || 0; }, set: function (v) { self._st = +v || 0; } },\\n      currentTime: { get: function () { return a.currentTime; } },\\n      duration: { get: function () { return isFinite(a.duration) ? a.duration : 0; } },\\n      paused: { get: function () { return a.paused; } },\\n      buffered: { get: function () { return a.buffered.length ? a.buffered.end(0) : 0; } }\\n    });\\n    this.obeyMuteSwitch = true;\\n    this.play = function () { var p = a.play(); if (p && p.catch) p.catch(function (e) { beacon(\'audio-play-blocked\', String(e && e.name)); }); };\\n    this.pause = function () { a.pause(); };\\n    this.stop = function () { self._stopping = true; a.pause(); try { a.currentTime = 0; } catch (_) {} self._stopping = false; hs.Stop.emit(); };\\n    this.seek = function (t) { try { a.currentTime = t; } catch (_) {} };\\n    this.destroy = function () { a.pause(); a.removeAttribute(\'src\'); audioLive--; };\\n    window.__audios = window.__audios || []; window.__audios.push(a);\\n  }\\n\\n  ";\nfunction fixture(file){\n const source=file===\'legacy\'?oldSource:fs.readFileSync(file,\'utf8\').split(\'// ---------- audio ----------\')[1].split(\'// ---------- file system manager ----------\')[0];\n const listeners={},audios=[],log=[];\n class Media{\n  constructor(){this.paused=true;this.loop=false;this.muted=false;this.volume=1;this.calls=0;this.h={};this.mode=\'blocked\';this.src=\'\';audios.push(this);}\n  addEventListener(t,fn){(this.h[t]??=[]).push(fn)}\n  play(){this.calls++;if(this.mode===\'blocked\')return Promise.reject(Object.assign(Error(\'autoplay\'),{name:\'NotAllowedError\'}));if(this.mode===\'error\')return Promise.reject(Object.assign(Error(\'decode\'),{name:\'NotSupportedError\'}));if(this.mode===\'deferred\')return new Promise((resolve,reject)=>{this.resolve=resolve;this.reject=reject});this.paused=false;return Promise.resolve();}\n  pause(){this.paused=true;}removeAttribute(){this.src=\'\';}\n }\n const doc={visibilityState:\'visible\',addEventListener(t,fn){(listeners[t]??=[]).push(fn)}};\n const ctx=vm.createContext({NAudio:Media,hub:()=>({on(){},off(){},emit(){}}),beacon:(...v)=>log.push(v),norm:v=>v,document:doc,window:{},hidden:false});\n vm.runInContext(source,ctx);const inner=new ctx.InnerAudio();inner.src=\'bgm.mp3\';inner.loop=true;\n return {ctx,doc,inner,media:audios[0],log,gesture(trusted=true){for(const fn of listeners.pointerdown||[])fn({isTrusted:trusted})}};\n}\nconst tick=()=>new Promise(r=>setImmediate(r));\n(async()=>{\n const results=[];\n async function test(name,fn){await fn();results.push({name,passed:true})}\n await test(\'old host reproduces blocked BGM without retry\',async()=>{const f=fixture(\'legacy\');f.inner.play();await tick();f.media.mode=\'ok\';f.gesture();await tick();assert.equal(f.media.calls,1);assert.equal(f.media.paused,true)});\n const current=path.join(root,\'ad-boost/scripts/trial_host/host/host.js\');\n await test(\'trusted gesture resumes rejected requested loop\',async()=>{const f=fixture(current);f.inner.play();await tick();f.media.mode=\'ok\';f.gesture();await tick();assert.equal(f.media.calls,2);assert.equal(f.media.paused,false);f.gesture();assert.equal(f.media.calls,2)});\n for(const [name,change] of [[\'paused\',f=>f.inner.pause()],[\'stopped\',f=>f.inner.stop()],[\'destroyed\',f=>f.inner.destroy()],[\'new source\',f=>f.inner.src=\'other.mp3\'],[\'zero volume\',f=>f.inner.volume=0],[\'muted\',f=>f.media.muted=true],[\'hidden document\',f=>f.doc.visibilityState=\'hidden\'],[\'hidden lifecycle\',f=>f.ctx.hidden=true],[\'one-shot effect\',f=>f.inner.loop=false]]){\n await test(name+\' does not restart\',async()=>{const f=fixture(current);f.inner.play();await tick();change(f);f.media.mode=\'ok\';f.gesture();await tick();assert.equal(f.media.calls,1)})}\n await test(\'synthetic input cannot unlock music\',async()=>{const f=fixture(current);f.inner.play();await tick();f.media.mode=\'ok\';f.gesture(false);assert.equal(f.media.calls,1)});\n await test(\'decode error not retried as autoplay denial\',async()=>{const f=fixture(current);f.media.mode=\'error\';f.inner.play();await tick();f.media.mode=\'ok\';f.gesture();assert.equal(f.media.calls,1)});\n await test(\'normal music continues without replay\',async()=>{const f=fixture(current);f.media.mode=\'ok\';f.inner.play();await tick();f.gesture();assert.equal(f.media.calls,1);assert.equal(f.media.paused,false)});\n await test(\'pause before rejection cancels stale request\',async()=>{const f=fixture(current);f.media.mode=\'deferred\';f.inner.play();f.inner.pause();f.media.reject(Object.assign(Error(),{name:\'NotAllowedError\'}));await tick();f.media.mode=\'ok\';f.gesture();assert.equal(f.media.calls,1)});\n await test(\'document replacement keeps native recovery listener\',async()=>{const f=fixture(current);f.inner.play();await tick();f.ctx.document={addEventListener(){throw Error(\'adapter document\')}};f.media.mode=\'ok\';f.gesture();await tick();assert.equal(f.media.paused,false)});\n console.log(JSON.stringify({passed:true,cases:results.length}));\n})().catch(e=>{console.error(e);process.exitCode=1});\n'
class AudioControls(unittest.TestCase):
 def test_audio_behavior_and_old_failure(self):
  if not shutil.which('node'):self.skipTest('node required')
  r=subprocess.run(['node','-e',JS,str(ROOT)],text=True,capture_output=True,check=True);d=json.loads(r.stdout);self.assertTrue(d['passed']);self.assertEqual(d['cases'],16)
 def test_handoff_rejects_stale_known_host(self):
  spec=importlib.util.spec_from_file_location('preview',ROOT/'remake-core/scripts/serve_preview.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
  current=(ROOT/'ad-boost/scripts/trial_host/host/host.js').read_text()
  with tempfile.TemporaryDirectory()as d:
   p=Path(d)/'__host/host.js';p.parent.mkdir();p.write_text(current);m.check_preview_host_audio(d)
   variants=[current.replace('function retryBlockedMusic(', 'function noRecovery('),current.replace('a.loop && !a.muted','a.loop && !a.muted',1).replace('a.volume > 0','a.volume >= 0'),current.replace('a.src = v ? norm(v)', 'a.muted = true; a.src = v ? norm(v)'),current.replace('a.volume = Math.max','unusedVolume = Math.max')]
   for source in variants:
    p.write_text(source)
    with self.assertRaises(SystemExit):m.check_preview_host_audio(d)
if __name__=='__main__':unittest.main()
